axum::middleware

Function from_extractor

Source

    pub fn from_extractor<E>() -> FromExtractorLayer<E, ()>

Expand description

Create a middleware from an extractor.

If the extractor succeeds the value will be discarded and the inner service will be called. If the extractor fails the rejection will be returned and the inner service will not be called.

This can be used to perform validation of requests if the validation doesn’t produce any useful output, and run the extractor for several handlers without repeating it in the function signature.

Note that if the extractor consumes the request body, as String or Bytes does, an empty body will be left in its place. Thus won’t be accessible to subsequent extractors or handlers.

§Example

    use axum::{
        extract::FromRequestParts,
        middleware::from_extractor,
        routing::{get, post},
        Router,
        http::{header, StatusCode, request::Parts},
    };

    // An extractor that performs authorization.
    struct RequireAuth;

    impl<S> FromRequestParts<S> for RequireAuth
    where
        S: Send + Sync,
    {
        type Rejection = StatusCode;

        async fn from_request_parts(parts: &mut Parts, state: &S) -> Result<Self, Self::Rejection> {
            let auth_header = parts
                .headers
                .get(header::AUTHORIZATION)
                .and_then(|value| value.to_str().ok());

            match auth_header {
                Some(auth_header) if token_is_valid(auth_header) => {
                    Ok(Self)
                }
                _ => Err(StatusCode::UNAUTHORIZED),
            }
        }
    }

    fn token_is_valid(token: &str) -> bool {
        // ...
    }

    async fn handler() {
        // If we get here the request has been authorized
    }

    async fn other_handler() {
        // If we get here the request has been authorized
    }

    let app = Router::new()
        .route("/", get(handler))
        .route("/foo", post(other_handler))
        // The extractor will run before all routes
        .route_layer(from_extractor::<RequireAuth>());

axum::middleware

Function from_fn

Source

    pub fn from_fn<F, T>(f: F) -> FromFnLayer<F, (), T>

Expand description

Create a middleware from an async function.

from_fn requires the function given to

• Be an async fn.

• Take zero or more FromRequestParts extractors.

• Take exactly one FromRequest extractor as the second to last argument.

• Take Next as the last argument.

• Return something that implements IntoResponse.

Note that this function doesn’t support extracting State. For that, use from_fn_with_state.

§Example

    use axum::{
        Router,
        http,
        routing::get,
        response::Response,
        middleware::{self, Next},
        extract::Request,
    };

    async fn my_middleware(
        request: Request,
        next: Next,
    ) -> Response {
        // do something with `request`...

        let response = next.run(request).await;

        // do something with `response`...

        response
    }

    let app = Router::new()
        .route("/", get(|| async { /* ... */ }))
        .layer(middleware::from_fn(my_middleware));

§Running extractors

    use axum::{
        Router,
        extract::Request,
        http::{StatusCode, HeaderMap},
        middleware::{self, Next},
        response::Response,
        routing::get,
    };

    async fn auth(
        // run the `HeaderMap` extractor
        headers: HeaderMap,
        // you can also add more extractors here but the last
        // extractor must implement `FromRequest` which
        // `Request` does
        request: Request,
        next: Next,
    ) -> Result<Response, StatusCode> {
        match get_token(&headers) {
            Some(token) if token_is_valid(token) => {
                let response = next.run(request).await;
                Ok(response)
            }
            _ => {
                Err(StatusCode::UNAUTHORIZED)
            }
        }
    }

    fn get_token(headers: &HeaderMap) -> Option<&str> {
        // ...
    }

    fn token_is_valid(token: &str) -> bool {
        // ...
    }

    let app = Router::new()
        .route("/", get(|| async { /* ... */ }))
        .route_layer(middleware::from_fn(auth));

